<?php
require_once __DIR__ . '/../../config/config.php';
require_roles(['ADMIN','HR']);
$pdo=db(); $employeeId=(int)($_GET['employee_id']??$_POST['employee_id']??0); $employees=$pdo->query('SELECT id,employee_number,first_name,last_name FROM employees ORDER BY last_name')->fetchAll(); $types=$pdo->query('SELECT id,name FROM document_types WHERE is_active=1 ORDER BY name')->fetchAll(); $templates=$pdo->query('SELECT id,name FROM document_templates WHERE is_active=1 ORDER BY name')->fetchAll(); $error=null;
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf(); phase2_require_employee($pdo,$employeeId); try{if(($_POST['form_action']??'')==='document'){$pdo->prepare('INSERT INTO employee_documents (employee_id,document_type_id,title,description,created_by) VALUES (?,?,?,?,?)')->execute([$employeeId,$_POST['document_type_id'],trim($_POST['title']),post_value('description'),$_SESSION['user_id']]);audit('DOCUMENT_CREATED','employee_documents',(int)$pdo->lastInsertId());flash('success','Employee document added.');}else{$q=$pdo->prepare('SELECT * FROM document_templates WHERE id=? AND is_active=1');$q->execute([(int)$_POST['template_id']]);$template=$q->fetch();if(!$template)throw new InvalidArgumentException('Select a valid template.');$content=render_template($template['content'],phase2_require_employee($pdo,$employeeId));$pdo->prepare('INSERT INTO document_drafts (employee_id,document_type_id,template_id,title,content,created_by) VALUES (?,?,?,?,?,?)')->execute([$employeeId,$template['document_type_id'],$template['id'],$template['name'],$content,$_SESSION['user_id']]);$draftId=(int)$pdo->lastInsertId();$pdo->prepare('INSERT INTO document_versions (draft_id,version_number,content,change_description,created_by) VALUES (?,?,?,?,?)')->execute([$draftId,1,$content,'Initial draft',$_SESSION['user_id']]);audit('DRAFT_CREATED','document_drafts',$draftId);flash('success','Draft created.');}redirect('records.php?employee_id='.$employeeId);}catch(Throwable $exception){$error=$exception->getMessage();}}
$employee=$employeeId?phase2_employee($pdo,$employeeId):null; $documents=[];$drafts=[];if($employee){$q=$pdo->prepare('SELECT d.*,t.name type_name FROM employee_documents d JOIN document_types t ON t.id=d.document_type_id WHERE d.employee_id=?');$q->execute([$employeeId]);$documents=$q->fetchAll();$q=$pdo->prepare('SELECT d.*,t.name type_name FROM document_drafts d JOIN document_types t ON t.id=d.document_type_id WHERE d.employee_id=?');$q->execute([$employeeId]);$drafts=$q->fetchAll();}$pageTitle='Employee records';require __DIR__.'/../../includes/header.php';?><div class="mb-7"><h1 class="font-display text-3xl font-bold">Employee records</h1><p class="text-sm text-slate-500">Documents and manual drafts</p></div><form class="bg-white border rounded-xl p-5 mb-6"><select name="employee_id" onchange="if(this.value)location.href='records.php?employee_id='+this.value" class="field !mt-0"><option value="">Choose an employee</option><?php foreach($employees as $item):?><option value="<?=$item['id']?>" <?=$employeeId===$item['id']?'selected':''?>><?=e($item['employee_number'].' · '.$item['first_name'].' '.$item['last_name'])?></option><?php endforeach;?></select></form><?php if($employee):?><div class="grid xl:grid-cols-2 gap-6"><section class="bg-white border rounded-xl p-6"><h2 class="font-display text-xl font-bold">Add document</h2><form method="post" class="space-y-3 mt-4"><?= csrf_field() ?><input type="hidden" name="employee_id" value="<?=$employeeId?>"><input type="hidden" name="form_action" value="document"><select name="document_type_id" required class="field !mt-0"><option value="">Document type</option><?php foreach($types as $type):?><option value="<?=$type['id']?>"><?=e($type['name'])?></option><?php endforeach;?></select><input name="title" required placeholder="Title" class="field"><textarea name="description" placeholder="Description" class="field"></textarea><button class="rounded-lg bg-teal-700 px-4 py-3 text-sm font-bold text-white">Add document</button></form></section><section class="bg-white border rounded-xl p-6"><h2 class="font-display text-xl font-bold">Create draft</h2><form method="post" class="space-y-3 mt-4"><?= csrf_field() ?><input type="hidden" name="employee_id" value="<?=$employeeId?>"><input type="hidden" name="form_action" value="draft"><select name="template_id" required class="field !mt-0"><option value="">Template</option><?php foreach($templates as $template):?><option value="<?=$template['id']?>"><?=e($template['name'])?></option><?php endforeach;?></select><button class="rounded-lg bg-slate-900 px-4 py-3 text-sm font-bold text-white">Generate draft</button></form></section></div><section class="bg-white border rounded-xl p-6 mt-6"><h2 class="font-display text-xl font-bold">Documents and drafts</h2><?php foreach($documents as $doc):?><p class="border-b py-3"><b><?=e($doc['title'])?></b> · <?=e($doc['type_name'])?> · <?=e($doc['status'])?></p><?php endforeach;?><?php foreach($drafts as $draft):?><p class="border-b py-3"><b><?=e($draft['title'])?></b> · <?=e($draft['status'])?> <a class="font-bold text-teal-700" href="draft.php?id=<?=$draft['id']?>">Open</a></p><?php endforeach;?></section><?php else:?><div class="bg-white border rounded-xl p-10 text-center text-slate-500">Choose an employee to manage records.</div><?php endif;?><?php require __DIR__.'/../../includes/footer.php';